begin;drop policy if exists expense_decisions_visible on public.expense_decisions;drop policy if exists expense_lines_visible on public.expense_lines;drop policy if exists expense_claims_owner_or_team on public.expense_claims;drop function if exists public.admin_decide_expense_claim(uuid,uuid,uuid,text,text);drop function if exists public.admin_submit_expense_claim(uuid,uuid,uuid,uuid,text);drop function if exists public.admin_save_expense_claim(uuid,uuid,uuid,uuid,text,jsonb);drop table if exists public.expense_operations;drop table if exists public.expense_decisions;drop table if exists public.expense_lines;drop table if exists public.expense_claims;delete from public.role_permissions where permission_key in('EXPENSE_VIEW_TEAM','EXPENSE_APPROVE');commit;